#!/usr/bin/env python3
"""Build the portfolio extension, retaining the original frozen inventory.
Run extend_inventory.py first; this renderer uses committed local inputs only.
"""
from pathlib import Path
import hashlib, html, json, shutil, sys
ROOT=Path(__file__).resolve().parent.parent
sys.path.insert(0,str(ROOT/'src'))
from extend_inventory import outputs

def esc(value): return html.escape(str(value),quote=True)
def load(name): return json.loads((ROOT/name).read_text(encoding='utf-8'))

def main():
    for name,raw in outputs().items():
        assert (ROOT/name).read_bytes()==raw, 'Regenerate '+name
    rows=load('data/builds-expanded.json'); catalog=load('governance/surface-catalog.json'); cells=load('data/cell-evidence.json')
    ext=load('governance/claim-integrity-extension.json'); cci=ext['cells']
    # Stable numbers identify surfaces; band order places 16 with Numbers and
    # 15 with Operation. They are column IDs, never a score or sequence of merit.
    groups=['Data','Numbers','Presentation','Operation']
    ordered=[s for group in groups for s in catalog if s['group']==group]
    symbols={'recorded':'●','limited':'◐','absent':'−','not_assessed':'?','not_applicable':'○'}
    names={'recorded':'Artifact recorded','limited':'Limited evidence','absent':'Not carried','not_assessed':'Not assessed','not_applicable':'Not applicable'}
    bandheads=''.join(f'<th scope="colgroup" colspan="{sum(s["group"]==g for s in ordered)}">{g}</th>' for g in groups)
    short_labels={1:'Rebuild',2:'Frozen inputs',3:'Sources',4:'Row counts',5:'Report',6:'Code tests',7:'Second path',8:'Golden cases',9:'Faults',10:'Charts',11:'Panel',12:'Metrics',13:'Run health',14:'Recon&shy;ciliation',15:'Expected events'}
    heads=''.join(f'<th scope="col" data-group="{s["group"]}"><button class="column-head" type="button" data-definition="{s["id"]}" aria-label="{s["number"]:02d} {esc(s["label"])}" title="Read definition: {esc(s["label"])}"><span>{s["number"]:02d}</span>{short_labels[s["number"]]}</button></th>' for s in ordered)
    table=[]
    for n,row in enumerate(rows,1):
        key=row['key']; short=row['name'].removeprefix('Cascadia ')
        titlelink=row.get('case_study','/projects/'+row['site_slug']+'.html')
        if not titlelink.startswith(('/', 'https://')): titlelink='/'+titlelink
        cols=[]
        for s in ordered:
            c=cells[key][s['id']]; state=c['state']; label=f'{short}: {s["label"]}. {names[state]}. Result: {c["result"]}. {c["summary"]}'
            href=c.get('href') if state not in ('not_assessed','absent') else None
            attrs=f'class="cell {state}" data-build="{key}" data-surface="{s["id"]}" aria-label="{esc(label)}" title="{esc(label)}"'
            mark=f'<a href="{esc(href)}" {attrs}>{symbols[state]}</a>' if href else f'<span {attrs} tabindex="0" role="img">{symbols[state]}</span>'
            cols.append(f'<td data-group="{s["group"]}">{mark}</td>')
        table.append(f'<tr data-row="{key}" class="{"latest" if key=="cascadia-claim-integrity" else ""}"><th scope="row"><span class="row-number">{n:02d}</span><a href="{titlelink}">{esc(short)}</a><small>{row["first_commit"]}{" · New" if key=="cascadia-claim-integrity" else ""}</small></th>'+''.join(cols)+'</tr>')
    definitions=[]
    for group in groups:
        details=''.join(f'<details id="definition-{s["id"]}"><summary><span class="definition-number">{s["number"]:02d}</span>{esc(s["label"])}{"<span class=tag>Added</span>" if s["new"] else ""}</summary><p>{esc(s["description"])}</p><a href="reference/surfaces.md">Read the counting rule</a></details>' for s in catalog if s['group']==group)
        definitions.append(f'<section class="definition-group"><h3>{group}</h3>{details}</section>')
    standard=load('data/standard.json')
    lane=''.join(f'<li><strong>v{esc(s["version"])}</strong><span>{esc(s["date"] or "Date not established")}</span></li>' for s in standard)
    options=''.join(f'<option value="{r["key"]}">{esc(r["name"].removeprefix("Cascadia "))}</option>' for r in rows)
    legend=''.join(f'<li><span class="legend-mark {key}" aria-hidden="true">{symbol}</span><span>{names[key]}</span></li>' for key,symbol in symbols.items())
    payload=json.dumps(dict(rows=rows,surfaces=catalog,cells=cells),ensure_ascii=False).replace('<','\\u003c')
    page=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light">
<title>Build by Build | Robbins Analytics</title><meta name="description" content="Eleven Cascadia builds, fifteen test surfaces, and the evidence and limits behind each recorded artifact.">
<link rel="canonical" href="https://www.robbinsanalytics.com/cascadia-build-by-build/">
<meta property="og:title" content="Build by Build: evidence, with its limits"><meta property="og:image" content="https://www.robbinsanalytics.com/assets/thumb-build-by-build.png">
<link rel="icon" href="assets/brand/favicon.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@1,500&family=Inter:wght@400;500;600;700&family=Inter+Tight:wght@500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
<link rel="stylesheet" href="assets/portfolio-extension.css"><script defer src="assets/portfolio-extension.js"></script></head>
<body><a class="skip" href="#main">Skip to content</a>
<header class="header"><a class="wordmark" href="/"><img src="assets/brand/robbins-mark.svg" width="28" height="28" alt="">Robbins <em>Analytics.</em></a><nav aria-label="Site"><a href="/cascadia.html">Cascadia</a><a href="/case-studies.html">Case studies</a><a href="/cascadia-claim-integrity/">Latest build <span aria-hidden="true">↗</span></a></nav></header>
<div class="reading-layout"><aside class="page-index"><nav aria-label="On this page"><p class="eyebrow">On this page</p><a href="#overview" aria-current="location">Overview</a><a href="#matrix">The matrix</a><a href="#new">Latest addition</a><a href="#definitions">Definitions</a><a href="#limits">Scope and limits</a><a href="#build-forward">Build forward</a><a href="#provenance">Provenance</a></nav></aside><main id="main" class="container"><section id="overview" class="hero"><div><p class="eyebrow">The Cascadia portfolio · Evidence inventory</p><h1>Build by <em>Build.</em></h1><p class="lede">What each build could check.<br>What the evidence can actually say.</p><p>Eleven independent portfolio builds. Fifteen test surfaces. A way to trace the controls each project carried, with failures and limits kept in view.</p><div class="actions"><a class="button dark" href="#matrix">Explore the evidence <span aria-hidden="true">↓</span></a><a class="button outline" href="#new">What changed</a></div></div>
<aside class="guide"><p class="eyebrow">Follow the evidence</p><h2>A file is a start.<br><em>Its result matters.</em></h2><p>A filled cell records an artifact. It does not say a check passed, every requirement was met, or the build is production ready.</p><a href="#matrix">Inspect the recorded evidence <span aria-hidden="true">↘</span></a></aside></section>
<section class="stats" aria-label="Inventory scope"><div><span>01 / Builds</span><strong>{len(rows)}</strong><p>Independent projects, in first-commit order</p></div><div><span>02 / Test surfaces</span><strong>{len(catalog)}</strong><p>The original fourteen, plus expected event accounting</p></div><div><span>03 / Added by Claim Integrity</span><strong>1</strong><p>Expected event accounting</p></div></section>
<section id="matrix" class="section matrix-section"><div class="section-head"><div><p class="eyebrow">The comparison</p><h2>Find the artifact.<br><em>Read the outcome.</em></h2></div><p>Compare all eleven builds, or narrow the rows by build and the columns by kind of check. Column numbers identify definitions, not scores.</p></div>
<div class="controls"><label>Build<select id="build-filter" aria-label="Build"><option value="all">All eleven builds</option>{options}</select></label><label>Kind of check<select id="group-filter" aria-label="Kind of check"><option value="all">All four groups</option>{''.join(f'<option>{g}</option>' for g in groups)}</select></label><button class="button outline" type="button" id="reset">Reset view</button></div>
<ul class="legend" aria-label="Cell legend">{legend}</ul><p class="matrix-hint" id="matrix-hint">Activate a filled cell to open its recorded artifact or verification summary directly. Column headings open definitions. On small screens, scroll the matrix; headers and build names stay visible. Artifact recorded is not a pass rating.</p>
<div class="matrix-scroll" tabindex="0" role="region" aria-label="Evidence matrix" aria-describedby="matrix-hint"><table><caption class="sr-only">Eleven builds by fifteen test surfaces.</caption><thead><tr class="bands"><th rowspan="2" scope="col" class="corner">Build / first commit</th>{bandheads}</tr><tr class="columns">{heads}</tr></thead><tbody>{''.join(table)}</tbody></table></div>
<p class="selection-count" id="selection-count" role="status">Showing 11 builds and 15 test surfaces.</p>
<noscript><p>The complete matrix and definitions remain visible. Interactive selection requires JavaScript; the <a href="reference/cell-evidence.json">complete evidence register</a> contains every path and recorded outcome.</p></noscript>
<p class="scope-note">Original ten builds: inventory frozen October 7, 2026, without a new outcome audit. Claim Integrity: repository evidence pinned to {esc(ext['source_commit'][:7])}; statuses come from the current scoped checklist and retained review evidence. A served snapshot can differ from a later repository artifact; the evidence register keeps both identities.</p></section>
<section id="new" class="section"><div class="section-head"><div><p class="eyebrow">The latest addition</p><h2>Missing work needs <em>its own evidence.</em></h2></div><p>Claim Integrity added expected event accounting: checking which records should exist, including work that never arrived. It also introduced this inventory's first recorded explicit N/A assessment.</p></div>
<div class="two-cards"><article class="feature"><span class="tag">15 / Operation</span><h3>Account for what should exist</h3><p>Expected event accounting starts from the triggering facts, rather than only the records that arrived. A missing claim or promised response remains an obligation.</p><p class="consequence">The question: what was due, at which cutoff, and is it still missing?</p><a href="#definition-expected_event_accounting">Read the definition ↓</a></article><article class="feature tint"><span class="tag">Completed / Claim Integrity</span><h3>Read the current checklist</h3><p>All 98 applicable golden-fixture variants pass, with 649 of 649 assertions compared. The restricted four-seat simulated panel and chart review are complete, with six clarity fixes and no open actionable findings.</p><p class="consequence">The dated prepublication checklist records 152 passes and six N/A requirements at its frozen-build scope and phase. Actual public readback later passed at publication.</p><a href="/cascadia-claim-integrity/#view=c">Inspect the completed records ↗</a></article></div>
<article class="applicability"><h3>Not every check applies to every build</h3><p>Scheduled-run evidence does not apply to Claim Integrity’s frozen module: it has no live data edge or continuing refresh claim. Applicability follows what a build does and claims. N/A is documented scope, not a passing test or missing evidence.</p></article><p class="scope-note">Expected event accounting is the additional inventory definition. Earlier builds have not been assessed against it. No first-ever capability claim or estate-wide standards change is implied.</p></section>
<section class="section" id="definitions"><div class="section-head"><div><p class="eyebrow">A shared vocabulary</p><h2>What each surface<br><em>is looking for.</em></h2></div><p>Open a definition for its purpose. The counting rules state which artifacts qualify and which do not. Limited evidence stays distinct from a completed requirement.</p></div><div class="definitions">{''.join(definitions)}</div></section>
<section id="limits" class="section limits"><p class="eyebrow">How far the comparison goes</p><h2>Traceable evidence.<br><em>Bounded claims.</em></h2><div class="three-cards"><article><h3>A chronology with evidence</h3><p>Different problems need different controls. Artifact counts are not quality, maturity or business-impact scores. Older rows retain their original inventory meanings and have not received a new outcome audit.</p></article><article><h3>Completed checks, stated scope</h3><p>Claim Integrity records 98/98 applicable fixture variants, 81/81 applicable public diagnostic injections and 22,173/22,173 numerical cells matching. Its chart review and four-seat restricted simulated panel are complete. The dated prepublication checklist records 152 passes and six N/A requirements at that scope and phase.</p></article><article><h3>Scope-appropriate N/A</h3><p>The frozen snapshot has no live edge, so scheduled operation is N/A. The panel uses simulated readers with a shared model service and workstation; certified blindness and human research are not claimed. Actual public readback later passed at publication; its prepublication N/A is not a continuing exemption.</p></article></div><a class="button dark" href="/cascadia-claim-integrity/case-study.html">Read the Claim Integrity case study ↗</a></section>
<section class="section" id="build-forward"><div class="section-head"><div><p class="eyebrow">Build-forward candidate</p><h2>Detection evaluation.<br><em>A future requirement.</em></h2></div><p>This candidate is outside the current test matrix for all eleven builds. Future work could use independently held faults and clean opportunities to measure misses, false alarms and detection timing across a declared roster.</p></div><details><summary>Historical context and limits for this candidate</summary><p>Claim Integrity's exploratory unblinded attempt 2 met must-catch in 20 of 26 represented classes, with six missed targets and ten of 36 classes unrepresented. It used older controls and shared custody. No final-control effectiveness or independent evaluator custody is claimed. These records remain context for future work, not a completed current surface.</p><a href="/cascadia-claim-integrity/case-study.html#forward">Read the candidate and retained disclosures ↗</a></details><p><a href="reference/build-forward.md">Candidate definition and proposed evidence</a></p></section>
<section id="provenance" class="section provenance"><details open><summary>Inventory provenance and design-standard history</summary><p>The original 10 × 14 inventory and standards history retain their October 7 freeze at <code>66b9de6</code>. This is an additive October 19 extension, not a claim that all eleven repositories were audited on one date. The refreshed row reads commit <code>{esc(ext['source_commit'])}</code>. The earlier extension remains in Git history and the provenance record.</p><p><a href="reference/extension-provenance.json">Provenance record</a> · <a href="reference/builds.json">Original ten-build snapshot</a> · <a href="reference/builds-expanded.json">Extended inventory</a> · <a href="reference/cell-evidence.json">Evidence and outcomes</a> · <a href="reference/surfaces.md">All counting rules</a></p><h3>VIZ-PRINCIPLES history in the original inventory</h3><ul class="standard-lane">{lane}</ul><p>Dates not established by the original history remain unknown. This lane is historical and does not claim current chart-review completion.</p></details></section>
</main></div><footer><a class="wordmark" href="/"><img src="assets/brand/robbins-mark-reversed.svg" width="28" height="28" alt="">Robbins <em>Analytics.</em></a><p>Portfolio projects. Evidence, scope and unresolved findings kept together.</p><a href="/case-studies.html">All case studies ↗</a></footer><script id="inventory-data" type="application/json">{payload}</script></body></html>'''
    (ROOT/'docs/index.html').write_text(page,encoding='utf-8',newline='\n')
    ref=ROOT/'docs/reference';ref.mkdir(exist_ok=True)
    for name in ['data/builds.json','data/builds-expanded.json','data/cell-evidence.json','data/standard.json','governance/surfaces.md','governance/build-forward.md','governance/extension-provenance.json','governance/surface-catalog.json','governance/claim-integrity-extension.json']:
        shutil.copyfile(ROOT/name,ref/Path(name).name)
    print('Rendered 11 × 15 matrix with outcomes, definitions and bounded claims.')
if __name__=='__main__': main()
